import {KEY, MEALS, DEFAULT_PROFILE, freshState, todayKey, dateShift, emptyDay, nutrition, summarize, recommendations, validateProfile, validateState, validateFood, mergeState, loadState, saveState, csvReport, GLUCOSE_CONTEXTS, glucoseToMmol, glucoseDisplay, validateGlucose, glucoseCsv} from './core.js';
import {FOODS, ACTIVITIES} from './data.js';
import {goalCards,glucosePanel,glucoseHistory,goalsSettings,glucoseForm} from './goals-ui.js';

const $ = (s, root=document) => root.querySelector(s);
const h = s => String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const round = (n,d=0) => Number.isFinite(n)?n.toLocaleString('zh-CN',{maximumFractionDigits:d}):'—';
const paths={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',chart:'M4 4v16h17M8 15l4-5 4 2 5-7',food:'M5 3v7m4-7v7M3 6h8m-4 4v11M19 3c-4 2-4 9 0 9V3Zm0 9v9',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8ZM9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1Z',cloud:'M6 18a5 5 0 0 1-1-10 7 7 0 0 1 13-1 5.5 5.5 0 0 1 0 11M12 12v10m-3-3 3 3 3-3',plus:'M12 5v14M5 12h14',arrow:'M7 17 17 7M7 7h10v10',left:'m14 6-6 6 6 6',right:'m10 6 6 6-6 6',check:'m5 12 4 4L19 6',close:'m6 6 12 12M6 18 18 6',run:'m6 20 4-7 4 3v5M7 10l4-4 4 5 5 1M11 6l1 6-4 2M16 3h.01',water:'M12 3c0 0-7 8-7 12a7 7 0 0 0 14 0c0-4-7-12-7-12ZM8 15a4 4 0 0 0 4 4',sun:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8ZM12 2v2m0 16v2M2 12h2m16 0h2M5 5l1 1m12 12 1 1M5 19l1-1M18 6l1-1',moon:'M20 15A8 8 0 0 1 9 4a8 8 0 1 0 11 11Z',snack:'M6 4h12v16H6ZM6 8h12M9 12h6m-6 4h3',edit:'m15 4 5 5-11 11H4v-5ZM13 6l5 5',trash:'M4 6h16M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7m4-7v7',book:'M4 4h7l1 2 1-2h7v16h-7l-1 1-1-1H4ZM12 6v15',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',upload:'M12 16V4m-5 5 5-5 5 5M4 16v5h16v-5',star:'m12 3 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1Z',shield:'m12 3 8 3v6c0 5-8 9-8 9S4 17 4 12V6ZM8 12l3 3 5-6',scale:'M5 6h14l2 15H3ZM9 6V3h6v3m-3 3v4',info:'M12 11v6m0-10h.01M22 12a10 10 0 1 0-20 0 10 10 0 0 0 20 0Z',leaf:'M5 19c-4-15 11-14 15-15 1 14-5 18-15 15Zm0 0L16 8',flame:'M13 2c3 6-2 7 2 10 1-1 2-3 2-4 7 9 2 14-5 14S2 14 7 8c-1 5 2 6 3 4 2-3-1-6 3-10Z',clock:'M12 6v6l4 2M22 12a10 10 0 1 0-20 0 10 10 0 0 0 20 0Z',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14Zm5 12 6 6'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.leaf}"/></svg>`;
let state, loadError='',saveError='';
try {state=loadState(localStorage);} catch(e) {state=freshState();loadError='现有记录暂时无法读取。为保护原数据，已暂停保存；请先到“数据与备份”下载原始存储。';}
let date=todayKey(),page='home',range=7,foodFilter='',modalContext={},undoState=null,toastTimer,installPrompt=null;
const navs=[['home','今日概览','home'],['trends','数据趋势','chart'],['foods','我的食物库','food'],['settings','个人与目标','settings'],['data','数据与备份','cloud']];
const day=()=>state.days[date]||emptyDay();
function touch(){if(!state.days[date])state.days[date]=emptyDay();if(!state.days[date].profile)state.days[date].profile={...state.profile};return state.days[date];}
function persist(message){
  if(loadError){toast('原数据受保护，请先导出并恢复备份。');return false;}
  try{saveState(localStorage,state);saveError='';if(message)toast(message);return true;}catch(e){saveError='本次修改尚未成功保存：存储空间不足或浏览器禁止存储。请到数据与备份导出当前记录。';toast(saveError,true);return false;}
}
function toast(message,error=false){clearTimeout(toastTimer);const el=$('#toast');el.textContent=message;el.className=`visible ${error?'error':''}`;toastTimer=setTimeout(()=>el.className='',5000);}
function modal(title,body,wide=false){const el=$('#modal');if(el.open)el.close();el.className=wide?'wide':'';el.innerHTML=`<div class="modal-header"><div><span class="eyebrow">YOUR DAILY BALANCE</span><h2 id="modal-title">${title}</h2></div><button class="icon-btn" data-action="close" aria-label="关闭弹窗">${icon('close')}</button></div>${body}`;el.showModal();}
const fields=(label,html,span=false)=>`<label class="field ${span?'full':''}"><span>${label}</span>${html}</label>`;
const input=(name,value='',type='number',extra='')=>`<input name="${name}" type="${type}" value="${h(value)}" ${extra}>`;
const sectionHead=(title,sub='',action='')=>`<div class="section-head"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${action}</div>`;
const addBtn=(action,label,extra='')=>`<button class="text-btn" data-action="${action}" ${extra}>${icon('plus')}${label}</button>`;
function shell(){
  const dt=new Date(`${date}T12:00:00`),isToday=date===todayKey();
  $('#app').innerHTML=`<aside class="sidebar"><a class="brand" href="#" data-action="nav" data-page="home"><img src="./icon.svg" width="42" height="42" alt=""><span>衡常<small>DAILY BALANCE</small></span></a><div class="sidebar-label">我的健康手账</div><nav aria-label="主导航">${navs.map(([id,label,ic])=>`<button class="nav-item ${page===id?'active':''}" data-action="nav" data-page="${id}" ${page===id?'aria-current="page"':''}>${icon(ic)}<span>${label}</span>${id===page?'<i></i>':''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="privacy-note">${icon('shield')}<span>属于你的小小空间<small>本地保存 · 自主备份</small></span></div><button class="profile-link" data-action="nav" data-page="settings"><span class="avatar">${h((state.profile.name||'我').slice(0,1))}</span><span>${h(state.profile.name||'我的个人空间')}<small>慢慢来，也很快。</small></span>${icon('right')}</button></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb">我的空间 <span>/</span> <strong>${navs.find(x=>x[0]===page)?.[1]}</strong></div><div class="topbar-right"><span class="saved"><i></i>${loadError?'存储待恢复':saveError?'有未保存的修改':'自动保存在此设备'}</span><button class="icon-btn" data-action="nav" data-page="data" aria-label="备份数据">${icon('cloud')}</button></div></header><main id="main" tabindex="-1">${loadError||saveError?`<div class="notice error-notice">${h(loadError||saveError)}</div>`:''}<div class="page-heading"><div><p class="eyebrow">${page==='home'?'A LITTLE BETTER, EVERY DAY':'YOUR PERSONAL HEALTH JOURNAL'}</p><h1>${page==='home'?'平衡，藏在每一天里。':({trends:'看见自己的变化',foods:'熟悉的食物，轻松记录',settings:'控糖目标与目标体重',data:'记录在手，安心常在'})[page]}</h1><p class="page-intro">${page==='home'?'好好吃饭，适度运动。把健康过成日常。':({trends:'关注一段时间的趋势，也接纳每一天的起伏。',foods:'每一次认真吃饭，都值得被记下。',settings:'以每日碳水、实测血糖和体重变化为重点。',data:'自动保存在浏览器，也可以导出或备份到 GitHub。'})[page]}</p></div>${page==='home'?`<div class="date-picker"><button class="icon-btn" data-action="date-prev" aria-label="前一天">${icon('left')}</button><label><span>${isToday?'今天 · ':''}${dt.toLocaleDateString('zh-CN',{month:'long',day:'numeric'})}<small>${dt.toLocaleDateString('zh-CN',{weekday:'long'})}</small></span><input aria-label="选择记录日期" id="selected-date" type="date" value="${date}" max="${todayKey()}"></label><button class="icon-btn" data-action="date-next" aria-label="后一天" ${isToday?'disabled':''}>${icon('right')}</button>${!isToday?'<button class="today-btn" data-action="today">今天</button>':''}</div>`:''}</div><div id="content"></div><footer class="footer"><span>衡常 · 让健康，有迹可循。</span><button data-action="about">计算说明与参考来源 ${icon('arrow')}</button></footer></main></div>`;
  renderContent();
}
function renderContent(){const el=$('#content');if(page==='home')el.innerHTML=home();if(page==='trends')el.innerHTML=trends();if(page==='foods')el.innerHTML=foodsPage();if(page==='settings')el.innerHTML=settings();if(page==='data')el.innerHTML=dataPage();}
function home(){
  const d=day(),s=summarize(d,state.profile),target=s.target,pct=target?Math.min(100,s.kcal/target*100):0;
  const recs=recommendations(d,s),hasBase=s.base!==null;
  return `${!Number(state.profile.targetWeight)||!Number(state.profile.carbs)?`<div class="welcome-strip"><span class="welcome-icon">${icon('leaf')}</span><div><strong>欢迎来到衡常，从认识自己开始。</strong><p>先设置每日碳水目标和目标体重，再记录实测血糖与体重变化。</p></div><button class="btn" data-action="nav" data-page="settings">设置个人目标 ${icon('right')}</button></div>`:''}${goalCards(state,date)}<div class="dashboard-top"><section class="energy-card"><div class="energy-main"><div class="card-kicker">${icon('leaf')} 今天，也在好好照顾自己</div><h2>每一餐，都是新的开始。</h2><p>记录当下的能量，找到舒服的平衡。</p><div class="energy-actions"><button class="btn primary" data-action="add-food">${icon('plus')}记录一餐</button><button class="btn subtle" data-action="add-exercise">${icon('run')}记录运动</button></div><div class="energy-legend"><span><i class="dot green"></i>已摄入 ${round(s.kcal)} kcal</span><span><i class="dot light"></i>基础摄入目标 ${hasBase?round(target)+' kcal':'待设置'}</span></div></div><div class="ring-wrap"><svg class="energy-ring" viewBox="0 0 180 180" aria-hidden="true"><circle class="ring-bg" cx="90" cy="90" r="75"/><circle class="ring-fill" cx="90" cy="90" r="75" stroke-dasharray="${pct*4.712} 471.24"/></svg><div class="ring-content"><span>已记录摄入</span><strong>${round(s.kcal)}</strong><small>kcal ${hasBase?' / '+round(target):''}</small></div><span class="ring-caption">${target?(s.kcal>target?'已超过基础摄入目标':'目标进度 '+round(pct)+'%'):'从第一餐开始'}</span></div></section><section class="balance-card"><div class="card-kicker">${icon('flame')} ${d.complete?'日终热量收支':'实时热量收支'}</div><div class="balance-number">${s.deficit===null?'—':round(Math.abs(s.deficit))}<small>kcal</small></div><span class="pill ${d.complete?'sage':'neutral'}">${s.deficit===null?'完善信息后估算':s.deficit<0?'当前热量盈余':'当前热量缺口'}${d.complete?' · 已结束记录':' · 未结算'}</span><div class="balance-lines"><span>基础日消耗 <b>${round(s.base)} <small>kcal</small></b></span><span>+ 运动净增加 <b>${round(s.net)} <small>kcal</small></b></span><span>− 饮食摄入 <b>${round(s.kcal)} <small>kcal</small></b></span></div><button class="explain-link" data-action="about">${icon('info')} 收支是如何计算的？</button></section></div><div class="stats-strip"><div><span class="stat-icon amber">${icon('food')}</span><div><small>已记餐次</small><strong>${new Set(d.foods.map(f=>f.meal)).size}<em>/ 4 餐</em></strong></div></div><div><span class="stat-icon peach">${icon('run')}</span><div><small>今日运动</small><strong>${round(s.minutes)}<em>分钟</em></strong></div></div><div><span class="stat-icon blue">${icon('water')}</span><div><small>今日饮水</small><strong>${round(d.water)}<em>ml</em></strong></div></div><button data-action="weight"><span class="stat-icon lilac">${icon('scale')}</span><div><small>今日体重 ${icon('edit')}</small><strong>${d.weight?round(Number(d.weight),1):'—'}<em>kg</em></strong></div></button></div><div class="dashboard-body"><div class="primary-column"><section class="panel meal-panel">${sectionHead('三餐与加餐','认真吃饭，也认真记录。',`<button class="text-btn" data-action="copy-day">${icon('book')}复制其他日期</button>`)}<div class="meal-grid">${Object.entries(MEALS).map(([key,label],i)=>mealCard(d,key,label,i)).join('')}</div></section><section class="panel">${sectionHead('营养，恰到好处','克数按食物重量自动换算；目标可在个人设置中调整。',`<button class="icon-btn" data-action="nav" data-page="settings" aria-label="设置营养目标">${icon('settings')}</button>`)}<div class="macro-grid">${[['protein','蛋白质','green'],['carbs','碳水化合物','amber'],['fat','脂肪','peach']].map(([k,label,color])=>`<div class="macro"><span><i class="dot ${color}"></i>${label}</span><strong>${round(s[k],1)}<small>g</small></strong><div class="progress"><i class="${color}" style="width:${Number(s.profile[k])?Math.min(100,s[k]/Number(s.profile[k])*100):0}%"></i></div><small>${s.profile[k]?'自定目标 '+s.profile[k]+' g':'尚未设置目标'}</small></div>`).join('')}</div><div class="fiber-line">已知膳食纤维 <b>${round(s.fiber,1)} g</b><small>${s.fiberUnknown?s.fiberUnknown+' 项缺少纤维数据，合计可能低估':'根据已记录食物计算'}</small></div></section>${glucosePanel(state,date)}<section class="panel journal-panel">${sectionHead('给今天留一句话','身体的感受，也值得被听见。')}<form id="journal-form"><textarea name="note" aria-label="今日感受" maxlength="3000" placeholder="今天的精神、饥饿感、运动感受，或一点小小的进步……">${h(d.note)}</textarea><div class="journal-bottom"><span class="muted">${d.complete?icon('check')+' 当天记录已结束，可继续修改':'三餐记齐后，再看看完整的一天。'}</span><div><button class="btn small" type="submit">保存日记</button><button class="btn small ${d.complete?'':'primary'}" type="button" data-action="complete">${icon(d.complete?'edit':'check')}${d.complete?'重新打开记录':'结束当天记录'}</button></div></div></form></section></div><div class="secondary-column"><section class="panel activity-panel">${sectionHead('动一动，好状态','把喜欢的运动，放进生活里。',addBtn('add-exercise','添加'))}${d.exercises.length?`<div class="exercise-list">${d.exercises.map(e=>{const single=summarize({...emptyDay(),exercises:[e],profile:d.profile,weight:d.weight},state.profile);return `<div class="exercise-row"><span class="exercise-symbol">${icon('run')}</span><div><strong>${h(e.name)}</strong><small>${e.minutes} 分钟 · ${e.mode==='manual'?'设备净消耗':e.met+' MET'}</small></div><div class="exercise-value">${round(single.net)}<small>kcal 净增加</small></div><button class="icon-btn" data-action="edit-exercise" data-id="${h(e.id)}" aria-label="修改${h(e.name)}">${icon('edit')}</button></div>`;}).join('')}</div>`:`<div class="empty-exercise"><div class="orbit">${icon('run')}</div><strong>今天，想怎么动一动？</strong><p>散步、骑行，或一场喜欢的训练。</p><button class="text-btn" data-action="add-exercise">记录第一项运动 ${icon('arrow')}</button></div>`}<div class="mini-summary"><span>运动总消耗（设备净值不提供总值） <b>${round(s.gross)} kcal</b></span><span>计入收支的净增加 <b>${round(s.net)} kcal</b></span></div></section><section class="panel water-panel">${sectionHead('喝口水，歇一歇','一点一点，补充今天的水分。')}<div class="water-display"><span class="water-icon">${icon('water')}</span><strong>${round(d.water)}<small>/ ${round(Number(s.profile.water))} ml</small></strong></div><div class="progress water-progress"><i style="width:${Math.min(100,d.water/Number(s.profile.water)*100)}%"></i></div><div class="water-actions"><button class="btn small" data-action="water" data-amount="-250" ${d.water<=0?'disabled':''}>− 250</button><button class="btn small" data-action="water" data-amount="250">+ 250 ml</button><button class="btn small" data-action="water-custom">自定义</button></div></section><section class="insight-panel"><div class="insight-heading">${icon('leaf')}<span>今天的小结</span><span class="pill">${d.complete?'日终':'进行中'}</span></div>${recs.map(r=>`<div class="insight-item ${r.type}"><h3>${r.title}</h3><p>${r.text}</p></div>`).join('')}<small class="insight-foot">基于记录和自定目标的规则提示 · 非医疗建议</small></section></div></div>`;
}
function mealCard(d,key,label,i){const fs=d.foods.filter(f=>f.meal===key),sum=fs.reduce((a,f)=>a+f.kcal,0);return `<article class="meal-card"><div class="meal-header"><span class="meal-symbol meal-${i}">${icon(['sun','food','moon','snack'][i])}</span><div><h3>${label}</h3><small>${['为一天补充能量','好好吃一顿午饭','给今天温柔收尾','一份小小的满足'][i]}</small></div><button class="icon-btn" data-action="add-food" data-meal="${key}" aria-label="添加${label}">${icon('plus')}</button></div>${fs.length?`<div class="food-entries">${fs.map(f=>`<button class="food-entry" data-action="edit-food" data-id="${h(f.id)}"><span>${h(f.name)}<small>${round(f.grams,1)} g</small></span><b>${round(f.kcal)}<small>kcal</small></b></button>`).join('')}</div>`:`<button class="empty-meal" data-action="add-food" data-meal="${key}">${icon('plus')} 记录${label}吃了什么</button>`}<div class="meal-total"><span>${fs.length?'本餐合计':'等待记录'}</span><b>${round(sum)} <small>kcal</small></b></div></article>`;}
function chart(days,metric='energy'){
  const w=800,ht=210,left=45,bottom=175,plotH=140,sw=w-left-15;
  const values=days.map(k=>{const d=state.days[k];return d?(metric==='weight'?(Number(d.weight)||null):summarize(d,state.profile).kcal):null;});
  const present=values.filter(v=>v!==null);
  if(!present.length)return `<div class="chart-empty">${icon(metric==='weight'?'scale':'chart')}<strong>${metric==='weight'?'还没有体重记录':'还没有饮食记录'}</strong><p>开始记录后，这里会慢慢画出你的变化。</p></div>`;
  const weightTarget=Number(state.profile.targetWeight)||null;
  const max=metric==='weight'?Math.max(...present,...(weightTarget?[weightTarget]:[]))+1:Math.max(1000,...present)*1.12,min=metric==='weight'?Math.max(0,Math.min(...present,...(weightTarget?[weightTarget]:[]))-1):0;
  const y=v=>bottom-(v-min)/(max-min)*plotH;
  let svg=`<svg viewBox="0 0 ${w} ${ht}" role="img" aria-label="${metric==='weight'?'体重':'摄入热量'}趋势，明细见下方表格">`;
  for(let i=0;i<4;i++){const val=min+(max-min)*i/3,yy=y(val);svg+=`<line x1="${left}" x2="${w-15}" y1="${yy}" y2="${yy}" stroke="#e9ece5" stroke-dasharray="3 5"/><text x="${left-8}" y="${yy+4}" text-anchor="end" fill="#849082" font-size="11">${round(val,metric==='weight'?1:0)}</text>`;}
  if(metric==='weight'&&weightTarget)svg+=`<line x1="${left}" x2="${w-15}" y1="${y(weightTarget)}" y2="${y(weightTarget)}" stroke="#bc9862" stroke-dasharray="5 5"/><text x="${w-20}" y="${y(weightTarget)-7}" text-anchor="end" fill="#9a7844" font-size="11">目标 ${round(weightTarget,1)} kg</text>`;
  const step=sw/days.length,bw=Math.min(36,step*0.5),points=[];
  days.forEach((k,i)=>{const x=left+step*(i+0.5),v=values[i];if(v!==null){if(metric==='energy')svg+=`<rect x="${x-bw/2}" y="${y(v)}" width="${bw}" height="${Math.max(1,bottom-y(v))}" rx="${Math.min(5,bw/2)}" fill="${state.days[k].complete?'#416e53':'#acc39c'}"><title>${k} ${round(v)} kcal${state.days[k].complete?'':'（未结算）'}</title></rect>`;else points.push([x,y(v),k,v]);}else svg+=`<circle cx="${x}" cy="${bottom-2}" r="2" fill="#d9dfd4"/>`;if(days.length<=7||i%5===0||i===days.length-1)svg+=`<text x="${x}" y="${bottom+22}" text-anchor="middle" fill="#849082" font-size="11">${k.slice(5).replace('-','/')}</text>`;});
  if(metric==='weight'){svg+=`<polyline points="${points.map(p=>`${p[0]},${p[1]}`).join(' ')}" fill="none" stroke="#5f8062" stroke-width="2.5" stroke-linejoin="round"/>`;for(const [x,yy,k,v] of points)svg+=`<circle cx="${x}" cy="${yy}" r="4" fill="#fff" stroke="#5f8062" stroke-width="2"><title>${k} ${v} kg</title></circle>`;}
  return `<div class="chart">${svg}</svg></div>`;
}
function trends(){const ds=Array.from({length:range},(_,i)=>dateShift(todayKey(),i-range+1)),recorded=ds.filter(k=>state.days[k]),complete=recorded.filter(k=>state.days[k].complete),ss=complete.map(k=>summarize(state.days[k],state.profile)).filter(s=>s.deficit!==null),avg=ss.length?ss.reduce((a,s)=>a+s.deficit,0)/ss.length:null;return `<div class="range-toolbar"><span class="muted">${ds[0].replaceAll('-','.')} — ${ds.at(-1).replaceAll('-','.')}</span><div class="segmented">${[7,30].map(n=>`<button class="${range===n?'selected':''}" data-action="range" data-range="${n}">近 ${n} 天</button>`).join('')}</div></div><div class="trend-stats"><div class="panel"><small>有记录的日子</small><strong>${recorded.length}<em>/ ${range} 天</em></strong></div><div class="panel"><small>已结束的完整记录</small><strong>${complete.length}<em>天</em></strong></div><div class="panel"><small>完整记录平均${avg!==null&&avg<0?'盈余':'缺口'}</small><strong>${avg===null?'—':round(Math.abs(avg))}<em>kcal</em></strong><small>有效估算 ${ss.length} 天</small></div><div class="panel"><small>累计运动</small><strong>${round(recorded.reduce((a,k)=>a+summarize(state.days[k],state.profile).minutes,0))}<em>分钟</em></strong></div></div><section class="panel">${sectionHead('饮食摄入趋势','浅色为未结束记录；空白日期代表未记录。')}<div class="chart-legend"><i class="dot green"></i>饮食摄入（kcal）</div>${chart(ds)}</section><section class="panel">${sectionHead('体重的缓慢变化','仅连接实际记录的体重；单日波动不代表长期变化。')}${chart(ds,'weight')}</section>${glucoseHistory(state,ds)}<section class="panel">${sectionHead('每日记录明细','点击日期可以回到当天，继续补充记录。',`<button class="text-btn" data-action="csv">${icon('download')}导出 CSV</button>`)}<div class="table-scroll"><table><thead><tr><th>日期</th><th>状态</th><th>摄入 kcal</th><th>运动净增加 kcal</th><th>缺口 / 盈余 kcal</th><th>蛋白质 g</th><th>体重 kg</th></tr></thead><tbody>${recorded.length?recorded.reverse().map(k=>{const d=state.days[k],s=summarize(d,state.profile);return `<tr><td><button class="text-btn" data-action="open-date" data-date="${k}">${k.slice(5).replace('-','月')}日</button></td><td><span class="pill ${d.complete?'sage':'neutral'}">${d.complete?'已结束':'进行中'}</span></td><td>${round(s.kcal)}</td><td>${round(s.net)}</td><td>${s.deficit===null?'—':round(Math.abs(s.deficit))+(s.deficit<0?' 盈余':' 缺口')}${!d.complete?' *':''}</td><td>${round(s.protein,1)}</td><td>${d.weight||'—'}</td></tr>`;}).join(''):'<tr><td colspan="7" class="table-empty">从今天开始，留下一点记录。</td></tr>'}</tbody></table></div><p class="help">平均热量收支只统计已结束且消耗信息完整的日期，避免将漏记或未完成的日期混入。</p></section>`;}
function allFoods(){return [...FOODS,...state.customFoods];}
function foodRows(query='',favorite=false){const fs=allFoods().filter(f=>(!favorite||state.favorites.includes(f.id))&&`${f.name} ${f.category}`.toLowerCase().includes(query.toLowerCase()));return fs.length?fs.map(f=>`<div class="library-row"><button class="favorite ${state.favorites.includes(f.id)?'is-favorite':''}" data-action="favorite" data-id="${h(f.id)}" aria-label="${state.favorites.includes(f.id)?'取消收藏':'收藏'}${h(f.name)}" aria-pressed="${state.favorites.includes(f.id)}">${icon('star')}</button><div class="library-food"><strong>${h(f.name)}</strong><small>${h(f.category)} · 每 100 g</small></div><b>${round(f.kcal)}<small> kcal</small></b><span class="library-macros">蛋 ${round(f.protein,1)} / 碳 ${round(f.carbs,1)} / 脂 ${round(f.fat,1)} g</span><button class="icon-btn" data-action="food-info" data-id="${h(f.id)}" aria-label="查看${h(f.name)}来源">${icon('info')}</button><button class="icon-btn" data-action="choose-food" data-id="${h(f.id)}" aria-label="记录${h(f.name)}">${icon('plus')}</button></div>`).join(''):`<div class="empty-state">${icon('search')}<strong>暂时没有找到</strong><p>试试其他名称，或根据包装创建自定义食物。</p></div>`;}
function foodsPage(){return `<section class="panel">${sectionHead('我的食物库',`内置 ${FOODS.length} 种参考食物 · 自定义 ${state.customFoods.length} 种。请匹配食物的生熟状态。`,`<button class="btn primary" data-action="custom-food">${icon('plus')}自定义食物</button>`)}<div class="search-row"><div class="search-box">${icon('search')}<input id="library-search" type="search" placeholder="搜索食物，如米饭、鸡蛋、苹果" value="${h(foodFilter)}" aria-label="搜索食物库"></div><label class="checkbox-label"><input id="favorites-only" type="checkbox">只看收藏</label></div><p class="help">营养值为食材参考估算，品牌、做法与份量会造成差异。烹调油、酱汁请单独记录；包装标示优先。</p><div id="library-results">${foodRows(foodFilter)}</div></section>`;}
function settings(){return goalsSettings(state.profile);}
function dataPage(){const count=Object.keys(state.days).length;return `<div class="data-intro"><span>${icon('shield')}</span><div><h2>你的记录，由你保管。</h2><p>目前共有 <b>${count}</b> 天记录、<b>${state.customFoods.length}</b> 种自定义食物。浏览器会自动保存；更换设备或清理浏览器前，请备份。</p></div><span class="pill sage">无广告 · 无追踪</span></div><div class="settings-grid"><section class="panel">${sectionHead('本地备份','完整 JSON 可恢复；CSV 方便用 Excel 查看。')}<div class="backup-option"><span>${icon('download')}</span><div><h3>导出完整记录</h3><p>包含个人资料、控糖目标、食物库和血糖等全部记录。</p></div><button class="btn" data-action="export">导出 JSON</button></div><div class="backup-option"><span>${icon('chart')}</span><div><h3>导出统计表格</h3><p>每日摄入、营养、运动和收支。</p></div><button class="btn" data-action="csv">导出 CSV</button></div><div class="backup-option"><span>${icon('book')}</span><div><h3>导出血糖记录</h3><p>包含日期、时点、读数、自定范围比较与备注。</p></div><button class="btn" data-action="glucose-csv">血糖 CSV</button></div><div class="backup-option"><span>${icon('upload')}</span><div><h3>从文件恢复</h3><p>先检查备份，再合并到当前记录。</p></div><button class="btn" data-action="import">导入 JSON</button><input type="file" id="import-file" accept=".json,application/json" hidden></div>${loadError?'<button class="btn" data-action="raw-export">下载原始存储以供恢复</button><button class="btn" data-action="recover">我已备份，重新初始化</button>':''}<div class="notice">导出的备份含个人记录，请自行保管。导入同一日期时，使用备份中的该日记录覆盖，并保留当前数据的自动恢复副本。</div><div class="backup-option"><span>${icon('clock')}</span><div><h3>恢复上一次导入前的记录</h3><p>每次导入前保存一份本地恢复副本。</p></div><button class="btn" data-action="restore-before-import">恢复</button></div></section><section class="panel">${sectionHead('GitHub 云端备份','由你主动上传与恢复，不会在后台自动发送。')}<form id="github-form"><div class="form-grid">${fields('仓库（用户名 / 仓库名）',input('repo',state.github.repo,'text','required placeholder="You-Sky/你的数据仓库" autocomplete="off"'),true)}${fields('分支',input('branch',state.github.branch,'text','required placeholder="main"'))}${fields('备份路径',input('path',state.github.path,'text','required placeholder="personal-data/health-data.json"'))}${fields('GitHub 访问令牌',`<input name="token" type="password" required autocomplete="off" placeholder="仅在本次操作中使用，不保存">`,true)}</div><p class="help">使用仅对目标仓库开放 Contents 读写权限的 fine-grained token。令牌只用于本次请求，不写入浏览器存储、导出文件或仓库。</p><div class="github-buttons"><button class="btn primary" type="submit" name="direction" value="upload">${icon('upload')}备份到 GitHub</button><button class="btn" type="submit" name="direction" value="download">${icon('download')}从 GitHub 恢复</button></div><p id="github-status" role="status" class="help"></p></form><details class="help-details"><summary>如何配置令牌与备份仓库</summary><p>在 GitHub 创建或选择一个数据仓库（需要已有分支），再创建 fine-grained personal access token，Repository access 仅选择该仓库，Repository permissions 的 Contents 选择 Read and write。请直接在上面的输入框中使用，不要把令牌写入代码或备份。</p><p>建议使用单独的私有仓库。若选择公开仓库，备份内容以及提交历史可被他人查看。网站本身发布在 GitHub Pages，不影响你选择其他仓库存放数据。</p><a href="https://github.com/settings/personal-access-tokens/new" target="_blank" rel="noopener noreferrer">前往 GitHub 配置令牌 ↗</a></details></section></div><div class="notice">${icon('info')} 本地记录按设备和浏览器保存，不会自动跨设备同步。网站离线后仍可记录；GitHub 备份需要网络。</div>`;}

function foodModal(meal='breakfast',id=null,foodId=null){
  const entry=id?day().foods.find(f=>f.id===id):null;
  const f=foodId?allFoods().find(f=>f.id===foodId):entry?{...entry,kcal:entry.kcal/entry.grams*100,protein:entry.protein/entry.grams*100,carbs:entry.carbs/entry.grams*100,fat:entry.fat/entry.grams*100,fiber:entry.fiber==null?null:entry.fiber/entry.grams*100}:null;
  modalContext={type:'food',meal:entry?.meal||meal,id,food:f};
  modal(entry?'修改食物记录':'给今天添一餐',`<form id="food-form"><div class="modal-body"><div class="meal-tabs">${Object.entries(MEALS).map(([k,l])=>`<label><input type="radio" name="meal" value="${k}" ${k===modalContext.meal?'checked':''}><span>${l}</span></label>`).join('')}</div>${f?selectedFoodForm(f,entry?.grams||100):`<div class="search-box">${icon('search')}<input id="food-search" type="search" placeholder="搜索食物，如米饭、鸡蛋" aria-label="搜索要记录的食物" autofocus></div><div class="modal-food-list" id="food-search-results">${searchFoodResults('')}</div><button class="text-btn" type="button" data-action="manual-entry">${icon('plus')}按包装营养标示手动输入</button>`}</div><div class="modal-footer">${entry?`<button class="btn danger" type="button" data-action="delete-food" data-id="${h(id)}">${icon('trash')}删除</button>`:'<span class="help">按实际食用的可食部分称重</span>'}<button class="btn primary" type="submit" ${!f?'disabled':''} id="food-save">${icon('check')}保存到当天</button></div></form>`);
}
function searchFoodResults(q){return allFoods().filter(f=>`${f.name} ${f.category}`.toLowerCase().includes(q.toLowerCase())).slice(0,30).map(f=>`<button class="food-choice" type="button" data-action="select-food" data-id="${h(f.id)}"><span class="food-choice-icon">${icon('food')}</span><span><strong>${h(f.name)}</strong><small>${h(f.category)} · 每 100 g</small></span><b>${round(f.kcal)}<small>kcal</small></b>${icon('right')}</button>`).join('')||'<div class="empty-state"><p>没有找到。可以根据包装标示手动输入。</p></div>';}
function selectedFoodForm(f,grams){return `<div class="selected-food"><span class="food-choice-icon">${icon('food')}</span><div><strong>${h(f.name)}</strong><small>每 100 g · ${round(f.kcal)} kcal</small></div><button class="text-btn" type="button" data-action="reselect-food">更换</button></div><div class="quantity-row">${fields('食用重量（g）',input('grams',grams,'number','required min="0.1" max="10000" step="0.1" autofocus'))}<div class="portion-buttons"><button class="btn small" type="button" data-action="portion" data-grams="50">50 g</button><button class="btn small" type="button" data-action="portion" data-grams="100">100 g</button><button class="btn small" type="button" data-action="portion" data-grams="200">200 g</button></div></div><div class="nutrition-preview" id="nutrition-preview">${nutritionPreview(f,grams)}</div><p class="help">${h(f.source||'该次记录保存的营养参考值')}。生熟重量需与条目一致；烹调油请单独记。</p>`;}
function nutritionPreview(f,g){const n=nutrition(f,g);return [['kcal','热量','kcal'],['protein','蛋白质','g'],['carbs','碳水','g'],['fat','脂肪','g']].map(([k,l,u])=>`<div><small>${l}</small><strong>${round(n[k],1)}<em>${u}</em></strong></div>`).join('');}
function customFoodModal(record=false){modalContext={type:record?'manual-entry':'custom-food',meal:modalContext.meal||'breakfast',id:modalContext.id};modal(record?'按营养标示记录':'创建自定义食物',`<form id="custom-food-form"><div class="modal-body"><div class="notice">请填写每 100 g 的营养值；若包装按每份标示，请先换算。仅填写热量时，其他营养素会按 0 计入。</div><div class="form-grid">${fields('食物名称',input('name','','text','required maxlength="100" placeholder="例如：我的酸奶"'),true)}${[['kcal','热量（kcal）',1000],['protein','蛋白质（g）',100],['carbs','碳水化合物（g）',100],['fat','脂肪（g）',100],['fiber','膳食纤维（g，可选）',100]].map(([k,l,m])=>fields(l,input(k,k==='kcal'?'':0,'number',`required min="0" max="${m}" step="0.01"`))).join('')}${record?fields('实际食用重量（g）',input('grams',100,'number','required min="0.1" max="10000" step="0.1"')):''}</div>${record?`<label class="checkbox-label"><input name="saveFood" type="checkbox" checked> 同时保存到我的食物库</label>`:''}</div><div class="modal-footer"><span class="help">数据来源：自行填写 / 包装标示</span><button class="btn primary" type="submit">保存${record?'记录':'食物'}</button></div></form>`);}
function exerciseModal(id=null){const e=id?day().exercises.find(x=>x.id===id):null;modalContext={type:'exercise',id};modal(e?'修改运动记录':'动一动，记下来',`<form id="exercise-form"><div class="modal-body"><div class="form-grid">${fields('计算方式',`<select name="mode" id="exercise-mode"><option value="met" ${e?.mode!=='manual'?'selected':''}>按运动强度和时长估算</option><option value="manual" ${e?.mode==='manual'?'selected':''}>输入设备活动热量（净消耗）</option></select>`,true)}${fields('选择运动',`<select id="activity-select"><option value="">自定义运动 / 自定 MET</option>${ACTIVITIES.map((a,i)=>`<option value="${i}" ${!e&&i===0?'selected':''}>${h(a.name)} · ${a.met} MET</option>`).join('')}</select>`,true)}${fields('运动名称',input('name',e?.name||ACTIVITIES[0].name,'text','required maxlength="100"'),true)}${fields('时长（分钟）',input('minutes',e?.minutes||30,'number','required min="1" max="1440" step="1"'))}${fields('强度（MET）',input('met',e?.met||ACTIVITIES[0].met,'number','required min="1" max="30" step="0.1"'))}${fields('设备活动热量 / 净消耗（kcal）',input('kcal',e?.kcal||0,'number','required min="0" max="20000" step="1"'),true)}</div><p class="help" id="exercise-preview"></p><div class="notice">估算方式会扣除同一时段的静息消耗。设备方式请填写“活动热量 / 净消耗”，不要填写已经包含静息代谢的全天总热量。</div></div><div class="modal-footer">${e?`<button class="btn danger" type="button" data-action="delete-exercise" data-id="${h(e.id)}">${icon('trash')}删除</button>`:'<span class="help">运动消耗仅为估算值</span>'}<button class="btn primary" type="submit">保存运动</button></div></form>`);updateExercisePreview();}
function updateExercisePreview(){const f=$('#exercise-form');if(!f)return;const values=Object.fromEntries(new FormData(f));const manual=values.mode==='manual';f.elements.met.disabled=manual;f.elements.kcal.disabled=!manual;$('#activity-select').disabled=manual;const e={...values,mode:values.mode,met:manual?1:Number(values.met),kcal:Number(values.kcal)||0,weight:Number(day().weight)||Number((day().profile||state.profile).weight)};const s=summarize({...emptyDay(),exercises:[e],profile:day().profile,weight:day().weight},state.profile);$('#exercise-preview').textContent=s.unresolved?'补充体重后才能估算；你也可以切换到设备活动热量。':`预计计入收支：${round(s.net)} kcal 净增加${manual?'':'（运动总消耗 '+round(s.gross)+' kcal）'}`;}
function glucoseModal(id=null){const reading=id?(day().glucose||[]).find(r=>r.id===id):null;modalContext={type:'glucose',id};modal(reading?'修改血糖读数':'记录一次实测血糖',glucoseForm(reading,state.profile));}
function simpleModal(kind){const d=day(),weight=kind==='weight';modal(weight?'记录今天的体重':'记下一杯水',`<form id="simple-form" data-kind="${kind}"><div class="modal-body">${fields(weight?'今日体重（kg）':'增加饮水（ml）',input('value',weight?d.weight:250,'number',weight?'required min="25" max="350" step="0.1" autofocus':'required min="1" max="5000" step="1" autofocus'))}<p class="help">${weight?'当日运动会优先使用记录的体重；已经按当时体重保存的运动不回溯修改。':'这里记录饮水量，饮品的热量请另记到餐食。'}</p></div><div class="modal-footer"><button class="btn primary" type="submit">保存</button></div></form>`);}
function about(){modal('每一笔收支，都有依据',`<div class="modal-body prose"><h3>每日收支</h3><div class="formula">热量缺口 = 基础日消耗 + 运动净增加 − 饮食摄入</div><p>正数为缺口，负数为盈余。基础日消耗采用你直接填写的数值，或静息代谢估算 × 日常活动系数；这里的活动系数不含另外录入的训练。不是将静息代谢和全天总消耗相加。</p><h3>静息代谢与运动</h3><p>Mifflin–St Jeor 简化公式：10 × 体重(kg) + 6.25 × 身高(cm) − 5 × 年龄 + 公式参数（男性 +5，女性 −161）。只面向一般成人；个体差异与活动系数都会影响精度。</p><p>运动总消耗 = MET × 3.5 × 体重(kg) ÷ 200 × 分钟。计入收支的净增加使用 (MET − 1)，扣除相同时间的静息能量。高日常活动系数仍可能与运动部分重叠，请按自身情况设置，勿重复录入设备全天消耗。</p><h3>三餐与营养</h3><p>每项食物按“每 100 g 营养 × 实际克数 ÷ 100”换算。数据库能量可能采用食物专用换算系数，所以不强制用蛋白质×4 + 碳水×4 + 脂肪×9覆盖食品标示热量。内置条目保留数据来源，生熟状态需一致；混合菜和外食请按标签或配方自定义。</p><h3>完整记录与建议</h3><p>未结束的日期只提供实时估算；趋势平均值仅统计已结束且能量信息完整的日期。总结由本地规则生成，对比你的自定目标，不调用 AI，也不上传数据。±150 kcal 用作界面上的接近目标提示，并非医学阈值。摄入目标不自动增加运动热量。</p><h3>控糖与目标体重</h3><p>每日碳水目标按总碳水克数比较，不推断血糖。血糖记录统一以 mmol/L 保存，mg/dL 按除以 18 换算；切换显示单位不会改写历史读数。空腹 / 餐前与餐后 2 小时采用各自的自定范围，睡前和随机读数仅记录。比较结果不等同诊断，手工测量次数也不等同连续血糖监测的达标时间。</p><p>起始体重与目标体重用于计算减重进度；最近体重只取选定日期及以前的实测记录。设置目标不要求填写热量目标。</p><h3>参考与设计灵感</h3><ul><li><a target="_blank" rel="noopener noreferrer" href="https://www.cdc.gov/diabetes/healthy-eating/carb-counting-manage-blood-sugar.html">CDC，碳水计数与个体化饮食目标</a></li><li><a target="_blank" rel="noopener noreferrer" href="https://www.niddk.nih.gov/health-information/diabetes/overview/managing-diabetes">NIDDK，血糖监测与个体化范围</a></li><li><a target="_blank" rel="noopener noreferrer" href="https://pubmed.ncbi.nlm.nih.gov/2305711/">Mifflin 等（1990），静息代谢预测方程</a></li><li><a target="_blank" rel="noopener noreferrer" href="https://pacompendium.com/adult-compendium/">2024 Adult Compendium，运动 MET 参考</a></li><li><a target="_blank" rel="noopener noreferrer" href="https://fdc.nal.usda.gov/">USDA FoodData Central，食物营养参考</a></li><li><a target="_blank" rel="noopener noreferrer" href="https://support.cronometer.com/hc/en-us/articles/360018171731-Diary-Overview">Cronometer 日记的分组与营养汇总设计</a></li><li><a target="_blank" rel="noopener noreferrer" href="https://github.com/wger-project/wger">wger 开源饮食、训练与体重记录设计</a></li></ul><p class="help">本网站为独立实现，仅参考功能思路。所有能量数字均为估算，不替代个体营养或医疗建议。</p></div>`,true);}
function download(content,name,mime){const u=URL.createObjectURL(new Blob([content],{type:mime}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),5000);}
function backup(){return JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2);}
function beforeRestore(){localStorage.setItem('hengchang.before-import',JSON.stringify(state));}
function previewImport(raw,origin='文件'){let incoming;try{incoming=validateState(raw);}catch(e){toast('备份未导入：'+e.message,true);return;}const count=Object.keys(incoming.days).length,overlap=Object.keys(incoming.days).filter(k=>state.days[k]).length;modalContext={type:'import',incoming};modal('检查并恢复备份',`<div class="modal-body prose"><p>来源：${h(origin)}</p><div class="import-summary"><strong>${count}<small>天记录</small></strong><strong>${incoming.customFoods.length}<small>种自定义食物</small></strong></div><p>将合并全部记录，并使用备份的个人资料。<b>${overlap} 个重复日期会使用备份中的整日记录覆盖。</b>当前其他日期和食物保留。</p><p class="help">导入前自动保留一份本地恢复副本，可在“数据与备份”中恢复。</p></div><div class="modal-footer"><button class="btn" data-action="close">取消</button><button class="btn primary" data-action="confirm-import">确认合并恢复</button></div>`);}
async function githubRequest(values,direction){
  const {repo,branch,path,token}=values,status=$('#github-status');
  if(!/^[A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+$/.test(repo)||!branch||branch.length>100||!path||path.startsWith('/')||path.split('/').some(x=>!x||x==='.'||x==='..')||!path.endsWith('.json')) throw new Error('请检查仓库、分支和 JSON 备份路径');
  if(/^(index\.html|app\.js|core\.js|data\.js|style\.css|manifest\.webmanifest)$/i.test(path))throw new Error('请选择专门的 JSON 数据备份路径');
  const headers={Accept:'application/vnd.github+json',Authorization:`Bearer ${token}`,'X-GitHub-Api-Version':'2022-11-28'};
  const request=async(url,options={})=>{const r=await fetch(url,{...options,headers:{...headers,...options.headers},signal:AbortSignal.timeout(25000)});if(r.status===401)throw new Error('令牌无效或已过期');if(r.status===403)throw new Error('权限不足或 API 请求受限，请检查令牌的 Contents 权限');return r;};
  status.textContent='正在连接 GitHub…';
  const metaR=await request(`https://api.github.com/repos/${repo}`);if(!metaR.ok)throw new Error('仓库不可用，请检查仓库名与令牌授权');const meta=await metaR.json();
  const fileUrl=`https://api.github.com/repos/${repo}/contents/${path.split('/').map(encodeURIComponent).join('/')}`;
  const oldR=await request(`${fileUrl}?ref=${encodeURIComponent(branch)}`);let old=null;if(oldR.ok)old=await oldR.json();else if(oldR.status!==404)throw new Error(`读取备份失败（${oldR.status}）`);
  if(direction==='download'){
    if(!old)throw new Error('指定分支中没有找到备份文件');if(old.encoding!=='base64'||!old.content)throw new Error('备份过大或文件格式不受支持');
    const bytes=Uint8Array.from(atob(old.content.replace(/\s/g,'')),c=>c.charCodeAt(0));const raw=JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(bytes));
    state.github={repo,branch,path};persist();status.textContent='备份已读取，等待确认恢复。';$('#github-form').elements.token.value='';previewImport(raw,`${repo} / ${path}`);return;
  }
  if(old){if(!old.content||old.encoding!=='base64')throw new Error('无法检查现有备份，请另选新的备份路径');try{validateState(JSON.parse(new TextDecoder().decode(Uint8Array.from(atob(old.content.replace(/\s/g,'')),c=>c.charCodeAt(0)))));}catch(e){throw new Error('目标路径已有其他内容，请改用一个新的备份路径以避免覆盖');}}
  const payload=backup();if(new TextEncoder().encode(payload).length>900000)throw new Error('备份已超过在线备份大小限制，请改用本地导出');
  modalContext={type:'github-upload',request,fileUrl,branch,repo,path,sha:old?.sha,payload};
  status.textContent='仓库已连接，请核对备份信息。';$('#github-form').elements.token.value='';
  modal('确认备份到 GitHub',`<div class="modal-body prose"><p>目标仓库：<b>${h(repo)}</b>（${meta.private?'私有':'公开'}）</p><p>路径：${h(path)}<br>分支：${h(branch)}</p><p>本次将上传个人资料、控糖与体重目标，以及 ${Object.keys(state.days).length} 天的饮食、运动、体重和血糖记录。${old?'会替换该路径的现有衡常备份；旧版本仍保存在 Git 提交历史中。':'会创建一个新的备份文件。'}</p>${!meta.private?'<div class="notice">这是公开仓库，备份内容和提交历史将可以被其他人查看。</div>':''}</div><div class="modal-footer"><button class="btn" data-action="close">取消</button><button class="btn primary" data-action="confirm-github">确认上传备份</button></div>`);
}

document.addEventListener('click',async ev=>{
  const b=ev.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,id=b.dataset.id;
  if(b.tagName==='A')ev.preventDefault();
  if(loadError&&!['nav','close','about','export','csv','raw-export','recover','confirm-recover','restore-before-import','confirm-restore','import','confirm-import'].includes(a)){toast('请先备份并恢复本地数据，或刷新读取最新记录。',true);return;}
  try{
    if(a==='nav'){page=b.dataset.page;shell();window.scrollTo({top:0,behavior:'instant'});}
    if(a==='close'){$('#modal').close();modalContext={};}
    if(a==='date-prev'||a==='date-next'){date=dateShift(date,a==='date-prev'?-1:1);shell();}
    if(a==='today'){date=todayKey();shell();}
    if(a==='open-date'){date=b.dataset.date;page='home';shell();window.scrollTo(0,0);}
    if(a==='range'){range=Number(b.dataset.range);renderContent();}
    if(a==='add-food')foodModal(b.dataset.meal||'breakfast');
    if(a==='choose-food')foodModal('breakfast',null,id);
    if(a==='edit-food')foodModal('breakfast',id);
    if(a==='select-food'){const meal=$('#food-form').elements.meal.value;foodModal(meal,modalContext.id,id);}
    if(a==='reselect-food'){const meal=$('#food-form').elements.meal.value,editId=modalContext.id;foodModal(meal);modalContext.id=editId;}
    if(a==='manual-entry'){modalContext.meal=$('#food-form').elements.meal.value;customFoodModal(true);}
    if(a==='custom-food')customFoodModal(false);
    if(a==='portion'){$('#food-form').elements.grams.value=b.dataset.grams;$('#nutrition-preview').innerHTML=nutritionPreview(modalContext.food,Number(b.dataset.grams));}
    if(a==='delete-food'){undoState=structuredClone(state);const d=touch();d.foods=d.foods.filter(x=>x.id!==id);persist('已删除，可通过页面下方的撤销按钮恢复');$('#modal').close();shell();showUndo();}
    if(a==='add-exercise')exerciseModal();
    if(a==='edit-exercise')exerciseModal(id);
    if(a==='delete-exercise'){undoState=structuredClone(state);touch().exercises=day().exercises.filter(x=>x.id!==id);persist('已删除运动');$('#modal').close();shell();showUndo();}
    if(a==='undo'&&undoState){state=undoState;undoState=null;persist('已撤销');shell();}
    if(a==='water'){const d=touch();d.water=Math.min(20000,Math.max(0,d.water+Number(b.dataset.amount)));persist();renderContent();}
    if(a==='water-custom')simpleModal('water');
    if(a==='weight')simpleModal('weight');
    if(a==='add-glucose')glucoseModal();
    if(a==='edit-glucose')glucoseModal(id);
    if(a==='delete-glucose'){undoState=structuredClone(state);touch().glucose=(day().glucose||[]).filter(r=>r.id!==id);persist('已删除血糖读数，可撤销');$('#modal').close();shell();showUndo();}
    if(a==='glucose-csv')download(glucoseCsv(state),`衡常血糖记录-${todayKey()}.csv`,'text/csv;charset=utf-8');
    if(a==='complete'){const d=touch();d.complete=!d.complete;persist(d.complete?'当天记录已结束，日终小结已更新':'已重新打开当天记录');renderContent();}
    if(a==='copy-day'){const available=Object.keys(state.days).filter(k=>k!==date&&state.days[k].foods.length).sort().reverse();modal('把熟悉的一餐再记一次',`<form id="copy-form"><div class="modal-body">${available.length?`${fields('从哪一天复制',`<select name="date">${available.map(k=>`<option value="${k}">${k}</option>`).join('')}</select>`)}${fields('复制哪些餐次',`<select name="meal"><option value="all">全部餐食</option>${Object.entries(MEALS).map(([k,l])=>`<option value="${k}">${l}</option>`).join('')}</select>`)}<p class="help">会追加到 ${date}，保留当天已有记录。请根据实际食用情况修改分量。</p>`:'<p class="muted">其他日期还没有餐食记录，先记下一餐吧。</p>'}</div><div class="modal-footer"><button class="btn primary" type="submit" ${available.length?'':'disabled'}>复制到当天</button></div></form>`);}
    if(a==='favorite'){state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];persist();$('#library-results').innerHTML=foodRows(foodFilter,$('#favorites-only')?.checked);}
    if(a==='food-info'){const f=allFoods().find(f=>f.id===id);modal(h(f.name),`<div class="modal-body prose"><p>每 100 g：${round(f.kcal,1)} kcal，蛋白质 ${round(f.protein,1)} g，碳水 ${round(f.carbs,1)} g，脂肪 ${round(f.fat,1)} g，膳食纤维 ${f.fiber==null?'未知':round(f.fiber,1)+' g'}。</p><p>来源：${h(f.source)}</p>${f.url?`<a target="_blank" rel="noopener noreferrer" href="${h(f.url)}">查看原始来源 ↗</a>`:''}<p class="help">数据为参考值。请匹配生熟状态，优先使用实际包装营养标示。</p></div>`);}
    if(a==='about')about();
    if(a==='export')download(backup(),`health-data-${todayKey()}.json`,'application/json');
    if(a==='csv')download(csvReport(state),`衡常每日统计-${todayKey()}.csv`,'text/csv;charset=utf-8');
    if(a==='import')$('#import-file').click();
    if(a==='confirm-import'){const incoming=modalContext.incoming;if(loadError){localStorage.setItem('hengchang.recovery-raw',localStorage.getItem(KEY)||'');loadError='';}beforeRestore();state=mergeState(state,incoming);if(persist('备份已合并恢复')){$('#modal').close();shell();}}
    if(a==='restore-before-import'){const raw=localStorage.getItem('hengchang.before-import');if(!raw)throw new Error('还没有导入前的恢复副本');modalContext={type:'restore',incoming:validateState(JSON.parse(raw))};modal('恢复导入前的记录',`<div class="modal-body prose"><p>将完整恢复到最近一次导入之前的本地状态，当前修改会被替换。建议先导出当前记录。</p></div><div class="modal-footer"><button class="btn" data-action="close">取消</button><button class="btn primary" data-action="confirm-restore">确认恢复</button></div>`);}
    if(a==='confirm-restore'){const next=modalContext.incoming;if(loadError){localStorage.setItem('hengchang.recovery-raw',localStorage.getItem(KEY)||'');loadError='';}beforeRestore();state=next;persist('已恢复导入前的记录');$('#modal').close();shell();}
    if(a==='raw-export')download(localStorage.getItem(KEY)||'',`health-data-raw-${todayKey()}.json`,'application/json');
    if(a==='recover')modal('重新初始化本地存储',`<div class="modal-body prose"><p>请确认已下载原始存储。下一步会用一个新的空白手账替换当前无法读取的存储。</p></div><div class="modal-footer"><button class="btn" data-action="close">取消</button><button class="btn danger" data-action="confirm-recover">已备份，重新开始</button></div>`);
    if(a==='confirm-recover'){const raw=localStorage.getItem(KEY);localStorage.setItem('hengchang.recovery-raw',raw||'');loadError='';state=freshState();persist('已重新初始化');$('#modal').close();shell();}
    if(a==='confirm-github'){
      b.disabled=true;b.textContent='正在上传…';const ctx=modalContext;
      const bytes=new TextEncoder().encode(ctx.payload);let binary='';for(const x of bytes)binary+=String.fromCharCode(x);
      const r=await ctx.request(ctx.fileUrl,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:`Back up health journal (${todayKey()})`,content:btoa(binary),branch:ctx.branch,...(ctx.sha?{sha:ctx.sha}:{})})});
      if(!r.ok){b.disabled=false;b.textContent='重试上传';throw new Error(r.status===409?'云端文件已改变，请关闭弹窗，重新获取备份后再上传':`上传未完成（${r.status}），请检查分支与权限`);}
      state.github={repo:ctx.repo,branch:ctx.branch,path:ctx.path};persist('备份已成功上传到 GitHub');modalContext={};$('#modal').close();shell();
    }
    if(a==='install'&&installPrompt){await installPrompt.prompt();installPrompt=null;}
  }catch(e){toast(e.message||'操作未完成，请重试',true);}
});
function showUndo(){const el=document.createElement('div');el.className='undo-bar';el.innerHTML=`<span>记录已删除</span><button class="text-btn" data-action="undo">撤销删除</button>`;$('#content').append(el);}
document.addEventListener('input',ev=>{
  if(ev.target.id==='food-search')$('#food-search-results').innerHTML=searchFoodResults(ev.target.value);
  if(ev.target.id==='library-search'){foodFilter=ev.target.value;$('#library-results').innerHTML=foodRows(foodFilter,$('#favorites-only').checked);}
  if(ev.target.name==='grams'&&modalContext.type==='food'&&modalContext.food)$('#nutrition-preview').innerHTML=nutritionPreview(modalContext.food,Number(ev.target.value)||0);
  if(ev.target.closest('#exercise-form'))updateExercisePreview();
});
document.addEventListener('change',async ev=>{
  if(ev.target.id==='glucose-unit'||ev.target.id==='reading-unit'){const form=ev.target.closest('form'),old=form.dataset.glucoseUnit||'mmol/L',next=ev.target.value,names=ev.target.id==='glucose-unit'?['fastingLow','fastingHigh','postMealLow','postMealHigh']:['value'];for(const name of names){const el=form.elements[name];if(el.value!=='')el.value=Number(glucoseDisplay(glucoseToMmol(el.value,old),next).toFixed(6));el.min=next==='mg/dL'?9:0.5;el.max=next==='mg/dL'?1080:60;}form.dataset.glucoseUnit=next;for(const label of form.querySelectorAll('.glucose-unit-label'))label.textContent=next;}

  if(ev.target.id==='selected-date'&&ev.target.value&&ev.target.value<=todayKey()){date=ev.target.value;shell();}
  if(ev.target.id==='favorites-only')$('#library-results').innerHTML=foodRows(foodFilter,ev.target.checked);
  if(ev.target.id==='activity-select'&&ev.target.value!==''){const a=ACTIVITIES[Number(ev.target.value)],f=$('#exercise-form');f.elements.name.value=a.name;f.elements.met.value=a.met;updateExercisePreview();}
  if(ev.target.id==='exercise-mode')updateExercisePreview();
  if(ev.target.id==='import-file'){try{const f=ev.target.files[0];if(!f)return;if(f.size>10000000)throw new Error('备份文件不能超过 10 MB');previewImport(JSON.parse(await f.text()));}catch(e){toast('无法读取备份：'+e.message,true);}ev.target.value='';}
});
document.addEventListener('submit',async ev=>{
  ev.preventDefault();const f=ev.target,v=Object.fromEntries(new FormData(f));
  if(loadError){toast('请先备份并恢复本地数据，或刷新读取最新记录。',true);return;}
  try{
    if(f.id==='food-form'){
      if(!modalContext.food)return;const grams=Number(v.grams),entry=validateFood({id:modalContext.id||crypto.randomUUID(),foodId:modalContext.food.id,name:modalContext.food.name,meal:v.meal,grams,...nutrition(modalContext.food,grams)},true),d=touch();
      if(modalContext.id)d.foods=d.foods.map(x=>x.id===modalContext.id?entry:x);else d.foods.push(entry);persist('已保存食物记录');$('#modal').close();shell();
    }
    if(f.id==='custom-food-form'){
      const food=validateFood({...v,id:crypto.randomUUID(),category:'自定义',source:'用户输入 / 包装标示'});
      if(modalContext.type==='manual-entry'){const grams=Number(v.grams),d=touch(),entry=validateFood({id:modalContext.id||crypto.randomUUID(),foodId:food.id,name:food.name,meal:modalContext.meal,grams,...nutrition(food,grams)},true);if(modalContext.id)d.foods=d.foods.map(x=>x.id===modalContext.id?entry:x);else d.foods.push(entry);if(v.saveFood)state.customFoods.push(food);}else state.customFoods.push(food);
      persist('自定义食物已保存');$('#modal').close();shell();
    }
    if(f.id==='exercise-form'){
      const p=day().profile||state.profile,e={id:modalContext.id||crypto.randomUUID(),name:v.name.trim(),mode:v.mode,minutes:Number(v.minutes),met:v.mode==='manual'?1:Number(v.met),kcal:v.mode==='manual'?Number(v.kcal):0,weight:Number(day().weight)||Number(p.weight)||null};
      const d=touch(),check=validateState({...state,days:{[date]:{...d,exercises:[e]}}}).days[date].exercises[0];if(modalContext.id)d.exercises=d.exercises.map(x=>x.id===modalContext.id?check:x);else d.exercises.push(check);persist('运动已保存');$('#modal').close();shell();
    }
    if(f.id==='simple-form'){const value=Number(v.value),d=touch();if(f.dataset.kind==='weight')d.weight=value;else d.water=Math.min(20000,d.water+value);persist('已保存');$('#modal').close();renderContent();}
    if(f.id==='glucose-form'){const d=touch(),reading=validateGlucose({id:modalContext.id||crypto.randomUUID(),context:v.context,time:v.time,meal:v.meal,value:glucoseToMmol(v.value,v.unit),sourceUnit:v.unit,note:v.note});if(modalContext.id)d.glucose=(d.glucose||[]).map(r=>r.id===modalContext.id?reading:r);else {if((d.glucose||[]).length>=300)throw new Error('当日血糖记录数量过多');(d.glucose??=[]).push(reading);}persist('实测血糖已保存');$('#modal').close();shell();}
    if(f.id==='profile-form'){
      const raw={...v,goal:'lose',deficit:v.deficit===''?0:v.deficit};for(const k of ['fastingLow','fastingHigh','postMealLow','postMealHigh'])raw[k]=v[k]===''||v[k]==null?'':glucoseToMmol(v[k],v.glucoseUnit||'mmol/L');if(!raw.startWeight&&raw.targetWeight&&raw.weight)raw.startWeight=raw.weight;const p=validateProfile(raw);
      const b=summarize(emptyDay(),p).base;if(b!==null&&b-Number(p.deficit)<500)throw new Error('目标缺口过大，请检查日消耗与目标');
      state.profile=p;if(state.days[todayKey()])state.days[todayKey()].profile={...p};persist('控糖与减重目标已保存，今天的记录已更新');shell();
    }
    if(f.id==='journal-form'){touch().note=v.note;persist('今天的感受已保存');}
    if(f.id==='copy-form'){const fs=state.days[v.date].foods.filter(x=>v.meal==='all'||x.meal===v.meal).map(x=>({...x,id:crypto.randomUUID()}));touch().foods.push(...fs);persist(`已复制 ${fs.length} 项食物，请核对当天的实际分量`);$('#modal').close();shell();}
    if(f.id==='github-form'){const buttons=[...f.querySelectorAll('button[type="submit"]')];buttons.forEach(b=>b.disabled=true);try{await githubRequest(v,ev.submitter?.value||'download');}finally{buttons.forEach(b=>b.disabled=false);f.elements.token.value='';}}
  }catch(e){toast(e.message||'保存失败，请检查输入',true);if(f.id==='github-form')$('#github-status').textContent=e.message;}
});
$('#modal').addEventListener('click',ev=>{if(ev.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(ev.clientX<r.left||ev.clientX>r.right||ev.clientY<r.top||ev.clientY>r.bottom){$('#modal').close();modalContext={};}}});
$('#modal').addEventListener('cancel',()=>{modalContext={};});
window.addEventListener('storage',ev=>{if(ev.key===KEY){toast('其他标签页更新了记录，请刷新后继续，避免覆盖。',true);loadError='其他标签页已更新记录，请刷新页面后再编辑。';}});
window.addEventListener('beforeinstallprompt',ev=>{ev.preventDefault();installPrompt=ev;});
shell();
if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
